{"command":"cat >> solar.py << 'PYEOF'

# ---------------- Debug printing ----------------
class Raw:
    __slots__=('s',)
    def __init__(self,s): self.s=str(s)
class DStruct:
    __slots__=('name','fields')
    def __init__(self,name,fields): self.name=name; self.fields=fields
class DVarStruct(DStruct): pass
class DVarTuple:
    __slots__=('name','args')
    def __init__(self,name,args): self.name=name; self.args=args
class DList:
    __slots__=('items','inline','prefix','suffix')
    def __init__(self,items,inline=False,prefix='[',suffix=']'): self.items=items; self.inline=inline; self.prefix=prefix; self.suffix=suffix
class DTuple:
    __slots__=('items',)
    def __init__(self,items): self.items=items

def rust_str(s):
    # Rust Debug string
    out='"'
    for ch in s:
        if ch=='"': out+='\\"'
        elif ch=='\\': out+='\\\\'
        elif ch=='\n': out+='\\n'
        elif ch=='\r': out+='\\r'
        elif ch=='\t': out+='\\t'
        elif ord(ch)<0x20: out+=f"\\u{{{ord(ch):x}}}"
        else: out+=ch
    out+='"'
    return out

def dbg(node, indent=0):
    pad=' '*indent
    pad4=' '*(indent+4)
    if node is None: return "None"
    if isinstance(node, Raw): return node.s
    if isinstance(node, str): return node
    if isinstance(node, DStruct):
        if not node.fields:
            return f"{node.name} {{}}"
        lines=[f"{node.name} {{"]
        for k,v in node.fields:
            vstr=dbg(v, indent+4)
            lines.append(f"{pad4}{k}: {vstr},")
        lines.append(f"{pad}}}")
        return "\n".join(lines)
    if isinstance(node, DVarTuple):
        if len(node.args)==0:
            return f"{node.name}()"
        lines=[f"{node.name}("]
        for a in node.args:
            lines.append(f"{pad4}{dbg(a, indent+4)},")
        lines.append(f"{pad})")
        return "\n".join(lines)
    if isinstance(node, DTuple):
        if not node.items: return "()"
        lines=["("]
        for a in node.items:
            lines.append(f"{pad4}{dbg(a, indent+4)},")
        lines.append(f"{pad})")
        return "\n".join(lines)
    if isinstance(node, DList):
        if not node.items: return f"{node.prefix}{node.suffix}"
        if node.inline:
            return node.prefix + ", ".join(dbg(x, indent) for x in node.items) + node.suffix
        lines=[node.prefix]
        for a in node.items:
            lines.append(f"{pad4}{dbg(a, indent+4)},")
        lines.append(f"{pad}{node.suffix}")
        return "\n".join(lines)
    if isinstance(node, (list,tuple)):
        return dbg(DList(list(node)), indent)
    return str(node)

def SomeD(v):
    if v is None: return Raw("None")
    return DVarTuple("Some",[v])
def opt_raw(v):
    # v is Raw/debug or None
    return SomeD(v) if v is not None else Raw("None")

class N:
    __slots__=('typ','span','docs','src')
    def __init__(self,typ,span=None):
        self.typ=typ; self.span=span; self.docs=[]; self.src=None
    # dynamic attrs via __dict__ fallback? slots prevent. We'll use extra dict.
class Node:
    def __init__(self,typ,span=None,**kw):
        self.typ=typ; self.span=span; self.docs=[]
        self.__dict__.update(kw)
    def __repr__(self): return f"Node({self.typ})"

def span_dbg(span):
    return Raw(repr(span)) if span else Raw("?")

# ---------------- Parser ----------------
class ParseAbort(Exception):
    pass

def tok_found(tok):
    if tok.kind=='eof': return "`<eof>`"
    if tok.kind=='ident': return f"`{tok.text}`"
    if tok.kind=='keyword': return f"keyword `{tok.text}`"
    if tok.kind=='reserved': return f"reserved keyword `{tok.text}`"
    if tok.kind=='elem': return "elementary type name"
    if tok.kind=='number': return "`<rational>`" if tok.is_rational else "`<integer>`"
    if tok.kind=='string': return "`<string>`"
    if tok.kind=='hexstring': return "`<string>`"
    return f"`{tok.text}`"

def format_expected(exp):
    # exp list of strings already formatted (without backticks handling included)
    if len(exp)==1: return f"expected {exp[0]}"
    return "expected one of " + ", ".join(exp[:-1]) + f", or {exp[-1]}"

def expected_label(exp, msg):
    if len(exp)==1:
        # identifier case no label
        if exp[0]=="identifier": return None
        return msg
    if len(exp)>6:
        return f"expected one of {len(exp)} possible tokens"
    return msg

GLOBAL_ITEM_MSG="expected global item (pragma, import directive, contract, interface, library, struct, enum, constant, function, modifier, or error definition)"
CONTRACT_ITEM_MSG="expected contract item (function, variable, struct, or modifier definition)"

class Parser:
    def __init__(self, src, tokens):
        self.src=src; self.toks=tokens; self.pos=0
        self.items=[]  # parsed source unit for recovery?
    def peek(self, k=0):
        idx=min(self.pos+k, len(self.toks)-1)
        return self.toks[idx]
    def cur(self): return self.peek(0)
    def advance(self):
        t=self.cur()
        if self.pos < len(self.toks)-1: self.pos+=1
        return t
    def at_eof(self): return self.cur().kind=='eof'
    def check(self, text=None, kind=None):
        t=self.cur()
        if kind and t.kind!=kind: return False
        if text and t.text!=text: return False
        return True
    def eat(self, text=None, kind=None):
        if self.check(text,kind):
            return self.advance()
        return None
    def error(self, message, span, label=None, children=None, secondary=None, code=None):
        d=Diag('error',message,span=span,label=label,code=code,children=children,secondary=secondary)
        emit_diag(d)
        raise ParseAbort()
    def err_expected(self, expected, tok=None, custom_msg=None, note=None):
        tok=tok or self.cur()
        # span for EOF: observed start at last char? Our EOF tok span is (n,n). Adjust:
        span=tok.span
        if tok.kind=='eof':
            n=len(self.src.text)
            if n>0:
                # Has original span (n-? ) If previous token end == n, eof location is... observed byte start = n-1 for "contract C {" (n=12, start11)
                # But for "foo" (len3) expected identifier found eof: span was 0..3 covering foo ? That was not EOF position - that parser's span was for "foo" token as name?
                # For generic expect at EOF after tokens ending at n, use last char span (n-1,n) (?) unless following whitespace/newline? If text ends with newline, offset n-1 is newline char, col would be after?
                # Test cases from echo pipes had newline; diag still pointed to '{' char, not newline. So clamp to last non-whitespace char.
                j=n-1
                while j>=0 and self.src.text[j] in ' \t\r\n': j-=1
                if j>=0: span=Span(self.src, j, j+1)
                else: span=Span(self.src,0,1)
            else:
                span=Span(self.src,0,1)
        msg = custom_msg or format_expected(expected)
        full = f"{msg}, found {tok_found(tok)}"
        label = None
        if not custom_msg:
            label=expected_label(expected, msg)
        # for custom global/contract messages, label none and note child
        children=None
        if note:
            children=[Diag('note', note)]
        self.error(full, span, label=label, children=children)
    def expect_punct(self, p):
        if self.check(p):
            return self.advance()
        self.err_expected([f"`{p}`"])
    def expect_kw(self, kw):
        if self.cur().kind in ('keyword','elem','reserved') and self.cur().text==kw:
            return self.advance()
        # also if ident? no
        self.err_expected([f"`{kw}`"])
    def expect_ident(self):
        t=self.cur()
        if t.kind=='ident':
            return self.advance()
        self.err_expected(["identifier"])
    # ---------- doc handling ----------
    def take_docs(self, tok=None):
        t=tok or self.cur()
        docs=getattr(t,'docs_before',[]) or []
        # convert to Node doc objects
        out=[]
        for kind,span,symbol in docs:
            dn=Node('DocComment', span); dn.kind_doc=kind; dn.symbol=symbol
            out.append(dn)
        return out

PYEOF
"}

