            kindmap={'notice':'Notice','title':'Title','author':'Author','dev':'Developer','param':'Param','return':'Return','returns':'Return','custom':'Custom','inheritdoc':'InheritDoc'}
            k=kindmap.get(tag, tag.capitalize())
            # span of tag name
            base = d.span.start + (3 if d.kind_doc=='Line' else 3)  # /// or /** : symbol starts after 3 chars
