            else: content_end=len(sym.rstrip())
            item=DStruct("NatSpecItem",[("kind",Raw(k)),("span",Raw(f"{d.span.src.display}:{d.span.src.line_col(tstart)[0]}:{d.span.src.line_col(tstart)[1]}: {d.span.src.line_col(tend)[0]}:{d.span.src.line_col(tend)[1]}")),("content_start",Raw(content_start)),("content_end",Raw(content_end))])
