def pragma_dbg(node):
    toks=node.tokens
    if toks and toks[0].text=='solidity':
        # Build semver req from raw text after 'solidity'
        # req tokens are toks[1:]
        req_toks=toks[1:]
        # Determine disjunction split by token '||'
        # Tokens are from lexer: operators like >= are punct tokens, versions are number tokens? Version "0.8.0" lexed as rational number 0.8 then .0 ??? Our lexer parses 0.8 as rational and stops, then .0 as rational starting dot. So toks may be fragmented.
        # Instead parse raw source text of pragma content.
        semi_end=node.span.end-1
        raw_start=toks[0].span.end
        raw=node.src if False else None
        # we have access via node.span.src
        src=node.span.src
        raw_text=src.text[raw_start:semi_end]
        # dis split
        dis=[]
        # Use regex scanning
        # Split by ||
        parts=[]
        last=0
        for m in re.finditer(r'\|\|', raw_text):
            parts.append((last,m.start())); last=m.end()
        parts.append((last,len(raw_text)))
        dis_dbg=[]
        for (ps,pe) in parts:
            part=raw_text[ps:pe]
            stripped=part.strip()
            if not stripped: continue
            part_start=raw_start+ps + (len(part)-len(part.lstrip()))
            part_end=raw_start+ps+len(part.rstrip())
            # components: range with ' - ' or space-separated comparators
            comps=[]
            # range check
            rm=re.search(r'(\d+\.\d+(?:\.\d+)?)\s*-\s*(\d+\.\d+(?:\.\d+)?)', stripped)
            if rm and stripped.strip().startswith(rm.group(1)):
                # range component spans part
                v1_start=part_start+rm.start(1); v1_end=v1_start+len(rm.group(1))
                v2_start=part_start+rm.start(2); v2_end=v2_start+len(rm.group(2))
                def ver_dbg(vtxt, vs, ve, extra=1):
                    # version span end + extra (observed)
                    span_raw=Raw(f"{src.display}:{src.line_col(vs)[0]}:{src.line_col(vs)[1]}: {src.line_col(ve+extra)[0]}:{src.line_col(ve+extra)[1]}")
                    return DStruct("SemverVersion",[("span",span_raw),("version",Raw(vtxt))])
                kind=DVarTuple("Range",[ver_dbg(rm.group(1),v1_start,v1_end,2), ver_dbg(rm.group(2),v2_start,v2_end,1)])
                comps.append(DStruct("SemverReqComponent",[("span",Raw(f"{src.display}:{src.line_col(part_start)[0]}:{src.line_col(part_start)[1]}: {src.line_col(part_end)[0]}:{src.line_col(part_end)[1]}")),("kind",kind)]))
            else:
                # tokenise comparators by regex
                for m in re.finditer(r'(>=|<=|>|<|=|\^|~)?\s*(\d+\.\d+(?:\.\d+)?)', stripped):
                    op=m.group(1); ver=m.group(2)
                    comp_start=part_start+m.start(); comp_end=part_start+m.end()
                    ver_start=part_start+m.start(2); ver_end=ver_start+len(ver)
                    opname={'^':'Caret','~':'Tilde','>':'Greater','<':'Less','>=':'GreaterEq','<=':'LessEq','=':'Eq'}.get(op) if op else None
                    ver_span=Raw(f"{src.display}:{src.line_col(ver_start)[0]}:{src.line_col(ver_start)[1]}: {src.line_col(ver_end+1)[0]}:{src.line_col(ver_end+1)[1]}")
                    verd=DStruct("SemverVersion",[("span",ver_span),("version",Raw(ver))])
                    kind=DVarTuple("Op",[SomeD(Raw(opname)) if opname else Raw("None"), verd])
                    comps.append(DStruct("SemverReqComponent",[("span",Raw(f"{src.display}:{src.line_col(comp_start)[0]}:{src.line_col(comp_start)[1]}: {src.line_col(comp_end)[0]}:{src.line_col(comp_end)[1]}")),("kind",kind)]))
            dis_dbg.append(DStruct("SemverReqCon",[("span",Raw(f"{src.display}:{src.line_col(part_start)[0]}:{src.line_col(part_start)[1]}: {src.line_col(part_end)[0]}:{src.line_col(part_end)[1]}")),("components",DList(comps))]))
        req=DStruct("SemverReq",[("dis",DList(dis_dbg))])
        return DVarTuple("Version",[Raw("solidity"), req])
    else:
        # Custom
        if toks:
            first=toks[0].text
            second=None
            if len(toks)>1: second=toks[1].text
            return DVarTuple("Custom",[DVarTuple("Ident",[Raw(first)]), SomeD(DVarTuple("Ident",[Raw(second)])) if second else Raw("None")])
        else:
            return Raw("Custom")

def item_dbg(item, src):
