        if kn.items_kind=='Plain':
            items=DVarTuple("Plain",[Raw("None")])
        elif kn.items_kind=='PlainAlias':
            items=DVarTuple("Plain",[SomeD(Raw(kn.alias_tok.text))])
        elif kn.items_kind=='Glob':
            items=DVarTuple("Global",[Raw(kn.alias_tok.text)])
        elif kn.items_kind=='Aliases':
