    elif kt=='ItemStruct':
        kind=DVarStruct("ItemKind::ItemStruct",[("name",Raw(kn.name_tok.text)),("fields",DList([vardef_dbg(f) for f in kn.fields]))])
    elif kt=='ItemEnum':
        kind=DVarStruct("ItemKind::ItemEnum",[("name",Raw(kn.name_tok.text)),("variants",DList([Raw(v.text) for v in kn.variants]))])
    elif kt=='ItemError':
        kind=DVarStruct("ItemKind::ItemError",[("name",Raw(kn.name_tok.text)),("parameters",paramlist_dbg(kn.params))])
    elif kt=='ItemEvent':
