        kind=DVarStruct("ItemKind::VariableDefinition", vd.fields)
    elif kt=='UsingDirective':
        kind=using_dbg(kn)
    else:
        kind=Raw(kt)
    return DStruct("Item",[("docs",doc_dbg_list(item.docs)),("span",span_dbg(item.span)),("kind",kind)])

def function_item_dbg(kn):
    # FunctionHeader
    vis=None
    if kn.visibility:
        vis=SomeD(DStruct("Spanned",[("span",span_dbg(kn.visibility.span)),("data",Raw(kn.visibility.text.capitalize()))]))
