# ---------------- Keccak ----------------
KECCAK_RC=[0x0000000000000001,0x0000000000008082,0x800000000000808A,0x8000000080008000,0x000000000000808B,0x0000000080000001,0x8000000080008081,0x8000000000008009,0x000000000000008A,0x0000000000000088,0x0000000080008009,0x000000008000000A,0x000000008000808B,0x800000000000008B,0x8000000000008089,0x8000000000008003,0x8000000000008002,0x8000000000000080,0x000000000000800A,0x800000008000000A,0x8000000080008081,0x8000000000008080,0x0000000080000001,0x8000000080008008]
KECCAK_R=[0,36,3,41,18, 1,44,10,45,2, 62,6,43,15,61, 28,55,25,21,56, 27,20,39,8,14]
def keccak256(data: bytes) -> bytes:
    # Keccak-f1600
    rate=136
    # padding pad10*1 with domain 0x01
    padded=bytearray(data)
    padded.append(0x01)
    while len(padded)%rate != rate-1:
        padded.append(0x00)
    padded.append(0x80)
    state=[[0]*5 for _ in range(5)]
    def rol(x,n):
        return ((x<<n)|(x>>(64-n))) & ((1<<64)-1) if n else x
    for off in range(0,len(padded),rate):
        block=padded[off:off+rate]
        for i in range(len(block)//8):
            lane=int.from_bytes(block[i*8:(i+1)*8],'little')
            x=i%5; y=i//5
            state[x][y]^=lane
        for rnd in range(24):
            # theta
            C=[state[x][0]^state[x][1]^state[x][2]^state[x][3]^state[x][4] for x in range(5)]
            D=[C[(x-1)%5]^rol(C[(x+1)%5],1) for x in range(5)]
            for x in range(5):
                for y in range(5): state[x][y]^=D[x]
            # rho pi
            B=[[0]*5 for _ in range(5)]
            for x in range(5):
                for y in range(5):
                    B[y][(2*x+3*y)%5]=rol(state[x][y], KECCAK_R[x+5*y])
            # chi
            for x in range(5):
                for y in range(5):
                    state[x][y]=B[x][y]^((~B[(x+1)%5][y]) & B[(x+2)%5][y])
            # iota
            state[0][0]^=KECCAK_RC[rnd]
    out=bytearray()
    while len(out)<32:
        for y in range(5):
            for x in range(5):
                out+=state[x][y].to_bytes(8,'little')
                if len(out)>=32: break
            if len(out)>=32: break
    return bytes(out[:32])

