class Decl:
    def __init__(self, kind, name, name_tok, kind_node, item, source_info, parent=None):
        self.kind=kind; self.name=name; self.name_tok=name_tok; self.node=kind_node; self.item=item; self.src_info=source_info; self.parent=parent
        self.signature=None; self.contract=None
        # for contracts
        self.bases=[]; self.base_nodes=[]; self.linearized=[]; self.member_scope={}; self.member_decls=[]; self.inherited_decls=[]
        self.source_order=0
    @property
    def span_name(self): return self.name_tok.span if self.name_tok else (self.item.span if self.item else self.node.span)
    @property
    def item_span(self): return self.item.span if self.item else self.node.span

