    # ---------- duplicate handling ----------
    def check_duplicate_in_scope(self, scope, decl, primary_span=None, allow_overload_kinds=('function','event')):
        """Add decl to scope dict (name->list). Return True if duplicate error."""
        name=decl.name
        if not name: return False
        existing=scope.get(name, [])
        if existing:
            # special overload for functions/events if decl kind same as all existing and signature differs
            if decl.kind in allow_overload_kinds and all(e.kind==decl.kind for e in existing):
                # signature comparison done separately as pair check; here allow adding
                existing.append(decl); return False
            # If decl is event and existing are functions? Original: event after function allowed (no error) - event adds despite?
            if decl.kind=='event' and all(e.kind!='event' for e in existing):
                existing.append(decl); return False
            prev=existing[0]
            d=self.err(f"identifier `{name}` already declared", primary_span or decl.span_name)
            d.child('note',"previous declaration declared here", span=prev.span_name)
            existing.append(decl)
            return True
        scope[name]=[decl]
        return False
    def check_function_event_overloads(self, decls):
        # pairwise same kind function/event same signature: error primary first, note other
        # Need signature computed
        seen={}
        for d in decls:
            if d.kind not in ('function','event'): continue
            if d.signature is None: continue
            key=(d.name, d.kind, d.signature)
            if key in seen:
                prev=seen[key]
                kindword='function' if d.kind=='function' else 'event'
                dd=self.err(f"{kindword} with same name and parameter types declared twice", prev.span_name)
                dd.child('note',"other declaration", span=d.span_name)
            else:
                seen[key]=d
    # ---------- scope building ----------
