    def resolve_bases_and_linearize(self):
        # first resolve base paths per contract
        for c in self.all_contracts:
            kn=c.node; info=c.src_info
            ctx=Ctx(self, info, contract=c)
            resolved=[]
            for b in kn.bases:
                toks=b.path_toks
                decl=self.resolve_path(toks, ctx, expect_contract=True)
                # self inherit check
                if decl is c:
                    self.err("contracts cannot inherit from themselves", toks[-1].span if len(toks)==1 else toks[0].span if False else toks[-1].span)
                    # original span is base name token (single)
                resolved.append(decl); c.base_nodes.append(b)
            c.bases=[d for d in resolved if d is not None]
            # definition precede: if base decl source_order > contract source_order and base in same ??? check all cases
            for d,bnode in zip(resolved, kn.bases):
                if d is not None and d is not c:
                    if d.source_order > c.source_order:
                        # Only if base source is same? If from imported file, its order in our program order may be after but imports are loaded before importer, parsed order puts importer first. So need check per source: if d.src_info order ??? Use declaration order within same file only? For cross-file, imported decl considered preceding.
                        if d.src_info is c.src_info:
                            self.err("definition of base has to precede definition of derived contract", c.name_tok.span)
            # linearization
            lin=self.linearize(c, set())
            if lin is None:
                self.err("linearization of inheritance graph impossible", c.name_tok.span)
                c.linearized=[c]
            else:
                c.linearized=lin
    def linearize(self, c, visiting):
        if id(c) in visiting: return None
        visiting=visiting|{id(c)}
        bases=c.bases
        if not bases: return [c]
        # duplicate bases => impossible
        if len(set(id(x) for x in bases))!=len(bases): return None
        # sequences: linearizations of bases in reverse order, plus reversed bases list
        seqs=[]
        for b in reversed(bases):
            lb=self.linearize(b, visiting)
            if lb is None: return None
            seqs.append(list(lb))
        seqs.append(list(reversed(bases)))
        # merge C3
        result=[c]
        seqs=[s for s in seqs if s]
        while seqs:
            # find candidate head that is not in tail of any seq
            candidate=None
            for s in seqs:
                head=s[0]
                if not any(head in other[1:] for other in seqs):
                    candidate=head; break
            if candidate is None: return None
            result.append(candidate)
            newseqs=[]
            for s in seqs:
                if s and s[0] is candidate: s=s[1:]
                if s: newseqs.append(s)
            seqs=newseqs
        return result
    def build_contract_scopes(self):
        # compute signatures first (needs scope ready)
        for c in self.all_contracts:
            for d in c.member_decls:
                if d.kind in ('function','event') and d.node.params is not None:
                    d.signature=tuple(canon_type_for_signature(p.ty, c.src_info, c, self) for p in d.node.params.vars)
        for c in self.all_contracts:
            scope={}
            # inherited members: from linearized excluding self, in linearization order
            inherited=[]
            seen_ids=set()
            for base in c.linearized[1:]:
                for md in base.member_decls:
                    if id(md) not in seen_ids:
                        inherited.append(md); seen_ids.add(id(md))
            c.inherited_decls=inherited
            # Start scope with inherited (no duplicate emission among inherited...)
            for md in inherited:
                if md.name:
                    scope.setdefault(md.name, []).append(md)
            # own: duplicate check against scope (incl inherited)
            own_scope={}
            for d in c.member_decls:
                if not d.name: continue
                # special ctor/fallback/receive duplicates handled elsewhere (they have no name)
                # Check own duplicate + inherited:
                # First own_scope check for function overload pair handled separately, but repeat against own other kinds:
                # Use combined logic:
                existing = scope.get(d.name, [])
                # determine if existing are only inherited vs own
                # We'll call check for own_scope tracking
                # Simpler: if any existing:
                if existing:
                    # if all existing are inherited and d is function and same kind, overriding/overload allowed -> no identifier error
                    # Cases: d variable vs inherited any => error; d function vs inherited variable/etc => error; d non-function vs inherited => error
                    is_inherited_only = all(e in inherited for e in existing)
                    if d.kind in ('function','event') and all(e.kind==d.kind for e in existing):
                        # allow (override or overload)
                        scope[d.name].append(d)
                    elif d.kind=='event' and all(e.kind!='event' for e in existing):
                        scope[d.name].append(d)
                    elif is_inherited_only and d.kind=='function' and all(e.kind=='function' for e in existing):
                        scope[d.name].append(d)
                    else:
                        # Check if this duplicate is only against inherited function and d is function with diff signature -> allowed above; otherwise err
                        # If existing includes own previous, err; if inherited only and d kind is modifier/struct etc, err as observed (state var)
                        prev=existing[0]
                        diag=self.err(f"identifier `{d.name}` already declared", d.span_name)
                        diag.child('note',"previous declaration declared here", span=prev.span_name)
                        scope[d.name].append(d)
                else:
                    scope[d.name]=[d]
                own_scope.setdefault(d.name, []).append(d)
            c.member_scope=scope
            # pairwise overload dup only own
            self.check_function_event_overloads(c.member_decls)
            # special ctor/fallback/receive
            for kindname,label in [('constructor','constructor'),('fallback','fallback'),('receive','receive')]:
                lst=[d for d in c.member_decls if d.kind==kindname]
                if len(lst)>1:
                    first=lst[0]
                    for other in lst[1:]:
                        diag=self.err(f"{label} function already declared", other.item_span)
                        diag.child('note',"previous declaration here", span=first.item_span)
            # function same name as contract
            for d in c.member_decls:
                if d.kind=='function' and d.name==c.name:
                    diag=self.err("functions are not allowed to have the same name as the contract", d.span_name)
                    diag.child('note',"if you intend this to be a constructor, use `constructor(...) { ... }` to define it")

class Ctx:
    def __init__(self, analyzer, info, contract=None):
        self.an=analyzer; self.info=info; self.contract=contract
