                    while off < len(src.text) and src.text[off] in ' \t\r\n': off+=1
                    sp=Span(src, off, off+1)
                    diag=self.err("expected a state variable declaration", sp)
                    diag.child('note',"this style of fallback function has been removed; use the `fallback` or `receive` keywords instead")
                else:
                    self._resolve_type(kk.ty, ctx)
