            else:
                self._resolve_type(kk.ty, ctx)
        elif kt=='ItemStruct':
            # fields
            # duplicate already in scope build? Struct field duplicates: check here (member scope duplicate not for struct fields)
            seen={}
            for f in kk.fields:
                if f.name_tok:
                    if f.name_tok.text in seen:
