def _check_unimplemented(self):
    for c in self.all_contracts:
        if c.node.kind_text=='Interface': continue
        # abstract token? contract item abstract_tok
        is_abstract = c.node.abstract_tok is not None
        # collect unimplemented functions: own + inherited where body is None and function kind
        unimpl=[]
        seen_sig=set()
        # Walk linearized: most derived first, if function implemented in a derived, it's implemented
        implemented=set()
        for contract in c.linearized:
            for d in contract.member_decls:
                if d.kind!='function': continue
                sig=(d.name, d.signature)
                if d.node.body is not None:
                    implemented.add(sig)
                else:
                    if sig not in implemented:
                        unimpl.append(d)
        # dedup unimpl by sig keeping first?
        uniq=[]; seen=set()
        for d in unimpl:
            sig=(d.name,d.signature)
            if sig not in seen: uniq.append(d); seen.add(sig)
        if uniq and not is_abstract:
            # For each? Original emitted one diag per contract with notes for each unimplemented
            # Primary span contract name, secondary span = `contract` keyword token? Their rendering: ┬─────── ━ . Secondary is kind_tok span (contract keyword 8 chars)
            diag=Diag('error', f"contract `{c.name}` has unimplemented functions", span=c.name_tok.span, code="3656", secondary=[(c.node.kind_tok.span, None)])
