    seen={}
    for cat,tok in kn.specs:
        if cat in seen:
            msgmap={'visibility':'visibility already specified','mutability':'state mutability already specified','virtual':'virtual already specified','override':'override already specified'}
            diag=self.err(msgmap.get(cat, f"{cat} already specified"), tok.span, secondary=[(seen[cat].span, "previous definition")])
        else: seen[cat]=tok
    item_span=decl.item_span
    # Named fallback/receive warning
    if kind=='function' and decl.name in ('fallback','receive'):
        diag=self.warn(f"function named `{decl.name}`", decl.span_name, code="3445")
        diag.child('help', f"remove the `function` keyword if you intend this to be a contract's {decl.name} function", span=decl.item_span)
    # contract named handled earlier
    # Free function
    is_free = contract is None and kind=='function'
    if is_free:
        if kn.visibility:
            diag=self.err("free functions cannot have visibility", item_span)
            diag.child('help', f"remove `{kn.visibility.text}` from the declaration")
        # free functions cannot have ??? virtual/override/modifiers? ignore
    # Kind specific
    if kind=='constructor':
        if kn.visibility and kn.visibility.text not in ('public','internal'):
            self.err(f"`{kn.visibility.text}` not allowed here; allowed values: internal, public", kn.visibility.span)
        if kn.mutability and kn.mutability.text!='payable':
            self.err(f"`{kn.mutability.text}` not allowed here; allowed values: payable", kn.mutability.span)
        if kn.virtual_tok:
            self.err("`virtual` is not allowed here", kn.virtual_tok.span)
    elif kind in ('fallback','receive'):
        if not kn.visibility:
            diag=self.err("no visibility specified", item_span)
            diag.child('help',"add `external` to the declaration")
        elif kn.visibility.text!='external':
            self.err(f"`{kn.visibility.text}` not allowed here; allowed values: external", kn.visibility.span)
        if kind=='receive':
            if kn.params and len(kn.params.vars)>0:
                self.err("receive ether function cannot take parameters", item_span)
            if not kn.mutability or kn.mutability.text!='payable':
                if kn.mutability:
                    self.err(f"`{kn.mutability.text}` not allowed here; allowed values: payable", kn.mutability.span)
                else:
