    for v in returns_vars:
        self._resolve_type(v.ty, ctx)
        self.validate_vardef(v, ctx, 'return')
    # duplicate among params+returns
    combined={}
    for v in all_params+returns_vars:
        if v.name_tok:
            nm=v.name_tok.text
            if nm in combined:
                prev=combined[nm]
                diag=self.err(f"identifier `{nm}` already declared", v.name_tok.span)
                diag.child('note',"previous declaration declared here", span=prev.name_tok.span)
            else: combined[nm]=v
