    for v in all_params+returns_vars:
        if v.name_tok: ctx.locals[-1][v.name_tok.text]=v
    for mod in kn.modifiers:
        toks=mod.path_toks
        # resolve modifier name: first tok lookup contract/global
        # Use lookup_type_first? Modifiers are in contract scope
        obj=None
        if ctx.contract and toks[0].text in ctx.contract.member_scope: obj=ctx.contract.member_scope[toks[0].text][0]
        elif ctx.info and toks[0].text in ctx.info.scope: obj=ctx.info.scope[toks[0].text][0]
        if obj is None:
            self.err(f"unresolved symbol `{toks[0].text}`", toks[0].span)
        else:
            # further segs?
            cur=obj
            for tok in toks[1:]:
                if cur.kind=='contract' and tok.text in cur.member_scope: cur=cur.member_scope[tok.text][0]
                else: self.err(f"unresolved symbol `{tok.text}`", tok.span); break
        if mod.args:
            for a in mod.args.args: self.resolve_expr(a, ctx)
