    if kn.override_paths:
        for path in kn.override_paths:
            self.resolve_path(path, ctx)
    ctx.pop()
    # validate function rules before body? Order in original: spec errors earlier maybe
    self.validate_function(decl, ctx)
    # body
    if kn.body:
        ctx.push({})
        for v in all_params+returns_vars:
            if v.name_tok: ctx.locals[-1][v.name_tok.text]=v
