        k=ty.kind
        if k[0]=='mapping':
            key_ty=k[1]
            inputs.append(param_obj_for_type(key_ty, "", inf, cont, an))
            traverse(k[3], inf, cont)
        elif k[0]=='array':
            inputs.append({"name":"","type":"uint256","internalType":"uint256"})
            traverse(k[1], inf, cont)
        else:
            out_for_value(ty, inf, cont)
