                if vis not in ('public','external'): continue
                inputs=[param_obj(v, d.src_info, cont, an) for v in d.node.params.vars]
                outputs=[param_obj(v, d.src_info, cont, an) for v in d.node.returns.vars] if d.node.returns else []
                entry={"type":"function","name":d.name,"inputs":inputs,"outputs":outputs,"stateMutability": mutability_str(d.node)}
                sig=f"{d.name}({','.join(signature_types(d.node.params.vars, d.src_info, cont, an))})"
            elif d.kind=='variable':
                if d.node.visibility and d.node.visibility.text=='public':
                    entry,sig=getter_objects(d, an)
                else: continue
            elif d.kind=='event':
                entry={"type":"event","name":d.name,"inputs":[param_obj(v, d.src_info, cont, an, event=True) for v in d.node.params.vars],"anonymous": bool(d.node.anonymous)}
                sig=f"{d.name}({','.join(signature_types(d.node.params.vars, d.src_info, cont, an))})"
            elif d.kind=='error':
                entry={"type":"error","name":d.name,"inputs":[param_obj(v, d.src_info, cont, an) for v in d.node.params.vars]}
                sig=f"{d.name}({','.join(signature_types(d.node.params.vars, d.src_info, cont, an))})"
            else:
                continue
            key=(entry["type"], entry.get("name",""), sig or "")
            if key in seen: continue
            seen.add(key)
            entries.append((entry,sig))
    def sort_key(es):
        entry,sig=es
        return (entry["type"], entry.get("name",""), sig or "")
    entries.sort(key=sort_key)
    return entries

def mutability_str(knode):
    if getattr(knode,'mutability',None):
        return {'pure':'pure','view':'view','payable':'payable'}.get(knode.mutability.text,'nonpayable')
    return 'nonpayable'

def build_output(source_infos, analyzer, emit_set):
    contracts={}
    # collect all contract decls
    all_contracts=[]
    for info in source_infos:
        for c in info.contracts: all_contracts.append(c)
    for c in all_contracts:
        key=f"{c.src_info.source.display}:{c.name}"
        entries=abi_for_contract(c, analyzer)
        cobj={}
        if 'abi' in emit_set:
