def type_max_slots(ty, info, contract, an, visited=None):
    k=ty.kind
    if k[0]=='array':
        size=k[2]
        if size is not None and size.typ=='Lit':
            try: n=int(size.tok.text.replace('_',''))
            except: n=1
            return n * type_max_slots(k[1], info, contract, an, visited)
        return 1
    if k[0]=='custom':
        ctx=Ctx(an, info, contract=contract) if an else None
        decl=an.resolve_path(k[1], ctx, silent=True) if an else None
        if decl is not None and not isinstance(decl,tuple) and decl.kind=='struct':
            if visited and id(decl) in visited: return 1
            visited=(visited or set())|{id(decl)}
            return 1+sum(type_max_slots(f.ty, decl.src_info, decl.parent, an, visited) for f in decl.node.fields)
        return 1
    return 1

def print_storage_sizes(analyzer):
