def qualified_name(decl):
    if decl.parent: return f"{decl.parent.name}.{decl.name}"
    return decl.name

def abi_type_info(ty, info, contract, an):
    k=ty.kind
    if k[0]=='elem':
        if k[1]=='address' and k[2]: return ("address","address payable",None)
        abi=canonical_elem(k[1]); return (abi,abi,None)
    if k[0]=='array':
        elem_abi, elem_internal, comps = abi_type_info(k[1], info, contract, an)
        size=k[2]
        suffix=f"[{size.tok.text.replace('_','')}]" if size is not None and size.typ=='Lit' else "[]"
        return (elem_abi+suffix, elem_internal+suffix, comps)
    if k[0]=='custom':
        ctx=Ctx(an, info, contract=contract) if an else None
        decl=an.resolve_path(k[1], ctx, silent=True) if an else None
        if decl is not None and not isinstance(decl,tuple):
            q=qualified_name(decl)
            if decl.kind=='struct':
                comps=[]
                for f in decl.node.fields:
                    comps.append(param_obj_for_type(f.ty, f.name_tok.text if f.name_tok else "", decl.src_info, decl.parent, an))
                return ("tuple", f"struct {q}", comps)
            if decl.kind=='enum': return ("uint8", f"enum {q}", None)
            if decl.kind=='udvt':
                uabi,_,_ = abi_type_info(decl.node.ty, decl.src_info, decl.parent, an)
                return (uabi, q, None)
            if decl.kind=='contract': return ("address", f"contract {q}", None)
            return (decl.name, decl.name, None)
        name=k[1][-1].text
        return (name, name, None)
    if k[0]=='mapping':
        return ("mapping","mapping",None)
    if k[0]=='function':
        return ("function","function",None)
    return ("","",None)

def param_obj_for_type(ty, name, info, contract, an):
    abi,internal,comps=abi_type_info(ty, info, contract, an)
    obj={"name":name,"type":abi,"internalType":internal}
    if comps is not None: obj["components"]=comps
    return obj

def param_obj(v, info, contract, an, event=False):
    abi,internal,comps=abi_type_info(v.ty, info, contract, an)
    if event:
        obj={"name": v.name_tok.text if v.name_tok else "", "type":abi, "indexed": bool(v.indexed), "internalType": internal}
    else:
        obj={"name": v.name_tok.text if v.name_tok else "", "type":abi, "internalType": internal}
    if comps is not None: obj["components"]=comps
    return obj

def signature_types(vars_list, info, contract, an):
    types=[]
    for v in vars_list:
        abi,_,_=abi_type_info(v.ty, info, contract, an)
        if abi.startswith("tuple"):
            # expand components canonical types
            # abi for struct: use canon_type which returns (....)
            types.append(canon_type(v.ty, info, contract, an))
        else:
            types.append(abi)
    return types

