    var=decl.node; info=decl.src_info; contract=decl.parent
    inputs=[]; outputs=[]
    def out_for_value(ty, inf, cont):
        # struct flatten
        k=ty.kind
        if k[0]=='custom':
            ctx=Ctx(an, inf, contract=cont)
            d=an.resolve_path(k[1], ctx, silent=True) if an else None
            if d is not None and not isinstance(d,tuple) and d.kind=='struct':
                for f in d.node.fields:
                    fk=f.ty.kind
