        info_by_id={id(x):x for x in infos}
        def visit(info):
            if id(info) in visited: return
            visited.add(id(info))
            for (_,target,_) in info.imports:
                if target is not None: visit(target)
            order.append(info)
        for info in infos: visit(info)
        # But for direct inputs without imports, keep original order; postorder does that.
        # For inputs A,C where C imports B, order A,B,C (visit A then C->B->C) good.
        self.hir_infos=order
        self.source_id={id(info):i for i,info in enumerate(order)}
        self.contract_id={}; self.function_id={}; self.variable_id={}; self.struct_id={}; self.enum_id={}; self.udvt_id={}; self.event_id={}; self.error_id={}
        self.functions=[]; self.variables=[]; self.contracts=[]; self.structs=[]; self.enums=[]; self.udvts=[]; self.events=[]; self.errors=[]
        self.expr_counter=0
        self.assign_ids()
    def item_id_str(self, decl):
        m={'contract':('ContractId',self.contract_id),'function':('FunctionId',self.function_id),'constructor':('FunctionId',self.function_id),'fallback':('FunctionId',self.function_id),'receive':('FunctionId',self.function_id),'modifier':('FunctionId',self.function_id),'variable':('VariableId',self.variable_id),'struct':('StructId',self.struct_id),'enum':('EnumId',self.enum_id),'udvt':('UdvtId',self.udvt_id),'event':('EventId',self.event_id),'error':('ErrorId',self.error_id)}
        if decl.kind not in m: return "ItemId::?"
