    def assign_ids(self):
        # contracts
        for info in self.hir_infos:
            for c in info.contracts:
                self.contract_id[id(c)]=len(self.contracts); self.contracts.append(c)
        # functions list: per source, walk items; contract functions in body order, free functions
        def add_function(d):
            if id(d) in self.function_id: return
            self.function_id[id(d)]=len(self.functions); self.functions.append(d)
        for info in self.hir_infos:
            for item in info.items:
                if item.kind_type=='ItemContract':
                    cdecl=next((c for c in info.contracts if c.item is item),None)
                    if cdecl:
                        for d in cdecl.member_decls:
                            if d.kind in ('function','constructor','fallback','receive','modifier'): add_function(d)
                        # getter functions synthetic after member functions of this contract (one per public var)
                        for d in cdecl.member_decls:
                            if d.kind=='variable' and d.node.visibility and d.node.visibility.text=='public':
                                # create synthetic decl marker stored on var decl
                                syn=Decl('function', d.name, d.name_tok, d.node, d.item, info, parent=cdecl)
                                syn.is_getter_for=d; syn.signature=()
