        for info in self.hir_infos:
            for d in self.all_decls_in_source(info):
                if d.kind=='struct': self.struct_id[id(d)]=len(self.structs); self.structs.append(d)
                elif d.kind=='enum': self.enum_id[id(d)]=len(self.enums); self.enums.append(d)
                elif d.kind=='udvt': self.udvt_id[id(d)]=len(self.udvts); self.udvts.append(d)
                elif d.kind=='event': self.event_id[id(d)]=len(self.events); self.events.append(d)
                elif d.kind=='error': self.error_id[id(d)]=len(self.errors); self.errors.append(d)
