            idx=len(self.variables); self.variable_id[node_key]=idx; self.variables.append((varnode,kind_hint)); return idx
        self.var_nodes={}  # id(varnode) -> (varnode,kind,decl-or-function)
        def register_var(varnode, kind, owner_decl=None, function_decl=None):
