                d.child('note', f"available source files: {disp_list}")
                emit_diag(d); all_match=False; parse_error=True
            else:
                dump_matched.extend(matched)
        if not all_match:
            dump_matched=None
    # AST dump
    if dump_kind=='ast' and not (dump_paths is not None and dump_matched is None):
        if dump_paths is None:
            # ParsedSources[...]
            src_dbgs=[]
            for info in infos:
                import_map=[]
                for (idx,target,imp) in info.imports:
                    if target is not None:
                        import_map.append((idx, infos.index(target)))
                src_dbgs.append(source_ast_dbg(info.source, info.ast, import_map))
            out=dbg(DList(src_dbgs, prefix="ParsedSources[", suffix="]"))+"\n"
            sys.stdout.write(out)
        else:
            for info in dump_matched:
                import_map=[]
                for (idx,target,imp) in info.imports:
                    if target is not None: import_map.append((idx, infos.index(target)))
                sys.stdout.write(dbg(source_ast_dbg(info.source, info.ast, import_map))+"\n")
