                    d=Diag('note', f"span #{n}", span=span); n+=1
                    sys.stderr.write(format_one_diag(d))
    if opts['stop_after'] is not None:
        err=flush_diags(True)
        return 1 if err else 0
    if parse_error:
        err=flush_diags(True); return 1 if err else 0
