    analyzer.analyze()
    # HIR dump
    if dump_kind=='hir':
        # even if errors, print
        try:
            hir_builder=HirBuilder(analyzer, infos)
            hir_dbg=hir_builder.build()
            sys.stdout.write(dbg(hir_dbg)+"\n")
            if dump_paths is not None:
                paths_dbg=DList([Raw(rust_str(p)) for p in dump_paths])
                sys.stdout.write("\nPaths not yet implemented: "+dbg(paths_dbg)+"\n")
        except Exception as e:
            # During development, surface? In production, suppress? We'll re-raise if env debug
            if os.environ.get('SOLAR_DEBUG'): raise
            pass
    if any(d.level=='error' for d in DIAGS):
        err=flush_diags(True); return 1 if err else 0
    if 'print-max-storage-sizes' in zflags:
        print_storage_sizes(analyzer)
    if 'typeck' in zflags:
        typeck(analyzer)
        if any(d.level=='error' for d in DIAGS):
            err=flush_diags(True); return 1 if err else 0
    # Emit
    if emit_set:
        output=build_output(infos, analyzer, emit_set)
        if opts['pretty_json']:
            text=json.dumps(output, indent=2, ensure_ascii=False)
        else:
            text=json.dumps(output, separators=(',', ':'), ensure_ascii=False)
        if opts['out_dir']:
            out_path=os.path.join(opts['out_dir'], "combined.json")
            try:
                with open(out_path,'w',encoding='utf-8') as f: f.write(text)
            except OSError as e:
                emit_diag(Diag('error', f"failed to write to output: {e.strerror} (os error {e.errno})"))
                flush_diags(True); return 1
        else:
            sys.stdout.write(text)
    # flush warnings/notes
    flush_diags(False)
    # If there were errors earlier not? Already handled.
    return 0

def source_matches_path(info, p, loader):
