    src=info.source
    if src.real is None:
        return p in ('stdin','<stdin>')
    if p==src.display or p==src.real: return True
    if not os.path.isabs(p):
        cand=os.path.realpath(os.path.join(os.getcwd(), p))
        if cand==src.real: return True
        cand2=os.path.realpath('/'+p)
        if cand2==src.real: return True
        # also "./display"
        if p=='./'+src.display: return True
    else:
