import pathlib
p=pathlib.Path("solar.py"); s=p.read_text()
start=s.index("def collect_spans(info):")
end=s.index("# ---------------- Typeck (minimal) ----------------")
new=r'''def collect_spans(info):
    spans=[]
    def add(span):
        if span: spans.append(span)
    def doc_spans(docs):
        for d in docs or []:
            add(d.span)
            sym=d.symbol
            tags=list(re.finditer(r'@([A-Za-z]+)', sym))
            if not tags:
                add(d.span)
            else:
                for m in tags:
                    tstart=d.span.start+3+m.start()+1
                    tend=tstart+len(m.group(1))
                    add(Span(d.span.src, tstart, tend))
    def walk_type(ty):
        if not ty: return
        add(ty.span)
        k=ty.kind
        if k[0]=='custom':
            toks=k[1]
            if toks: add(Span(ty.span.src, toks[0].span.start, toks[-1].span.end))
            for t in toks: add(t.span)
        elif k[0]=='array':
            walk_type(k[1])
            if k[2] is not None: walk_expr(k[2])
        elif k[0]=='mapping':
            walk_type(k[1])
            if k[2] is not None: add(k[2].span)
            walk_type(k[3])
        elif k[0]=='function':
            _,params,vis,mut,returns=k
            walk_paramlist(params)
            if returns: walk_paramlist(returns)
    def walk_var(v):
        if not v: return
        add(v.span); walk_type(v.ty)
        if getattr(v,'name_tok',None): add(v.name_tok.span)
        if getattr(v,'initializer',None): walk_expr(v.initializer)
    def walk_paramlist(pl):
        if not pl: return
        for v in pl.vars: walk_var(v)
        add(pl.span)
    def walk_callargs(args):
        if not args: return
        add(args.span)
        if getattr(args,'named',None):
            for (n,val) in args.named.opts:
                add(n.span); walk_expr(val)
        else:
            for a in args.args: walk_expr(a)
    def walk_expr(e):
        if not e: return
        add(e.span)
        t=e.typ
        if t=='Lit':
            # Lit inner span: for lit node, tok span may differ for units; oracle uses expr/lit same full span
            add(e.span)
        elif t=='Ident':
            add(e.span)
        elif t in ('Binary',):
            walk_expr(e.lhs); walk_expr(e.rhs)
        elif t in ('Unary','Postfix'):
            walk_expr(e.expr)
        elif t=='Member':
            walk_expr(e.expr); add(e.member_tok.span)
        elif t=='Index':
            walk_expr(e.expr)
            if e.index: walk_expr(e.index)
            if getattr(e,'slice_end',None): walk_expr(e.slice_end)
        elif t=='Call':
            # options wrapper first
            if getattr(e,'options',None):
                # CallOptions expr span
                add(Span(e.span.src, e.func.span.start, e.options.span.end))
                walk_expr(e.func)
                for (n,val) in e.options.opts:
                    add(n.span); walk_expr(val)
            else:
                walk_expr(e.func)
            walk_callargs(e.args)
        elif t in ('Tuple','ArrayLit'):
            for x in e.elems:
                if x is not None: walk_expr(x)
        elif t=='Ternary':
            walk_expr(e.cond); walk_expr(e.true); walk_expr(e.false)
        elif t=='New':
            walk_type(e.ty)
        elif t=='TypeExpr':
            walk_type(e.ty)
        elif t=='TypeExpr2':
            walk_type(e.ty)
        elif t=='PayableCall':
            walk_callargs(e.args)
        else:
            # generic children exprs
            for v in e.__dict__.values():
                if isinstance(v, Node) and v.typ not in ('Type',): walk_expr(v)
                elif isinstance(v,(list,tuple)):
                    for x in v:
                        if isinstance(x, Node): walk_expr(x)
    def walk_block(block, is_stmt=False):
