new=r'''def format_ast_stats(infos):
    sizes={'SourceUnit':16,'DocComments':8,'Span':8,'Item':160,'ItemContract':48,'ItemFunction':144,'VariableDefinition':72,'ItemStruct':24,'ItemEnum':24,'ItemEvent':32,'ItemError':32,'ItemUdvt':40,'PragmaDirective':32,'ImportDirective':32,'UsingDirective':48,'ParameterList':16,'Block':16,'Stmt':64,'Expr':48,'Lit':88,'Ident':12,'PathSlice':12,'Type':24,'CallArgs':24}
    counts={}; cats={}
    def inc(name, cat=None):
        counts[name]=counts.get(name,0)+1
        if cat:
            cats.setdefault(name,{})[cat]=cats.setdefault(name,{}).get(cat,0)+1
    def incspan(): inc('Span')
    def walk_expr(e):
        if e is None: return
        catmap={'Lit':'Lit','Ident':'Ident','Binary':'Binary','Call':'Call','Member':'Member','Index':'Index','Ternary':'Ternary','Tuple':'Tuple','ArrayLit':'Array','New':'New','TypeExpr':'Type','TypeExpr2':'TypeCall','PayableCall':'Payable'}
        cat=catmap.get(e.typ, e.typ)
        if e.typ=='Unary' or e.typ=='Postfix':
            cat='Delete' if getattr(e,'op_tok',None) and e.op_tok.text=='delete' else 'Unary'
        if e.typ=='Binary' and e.kind=='assign': cat='Assign'
        inc('Expr',cat); incspan()
        t=e.typ
        if t=='Lit': inc('Lit')
        elif t=='Ident': inc('Ident')
        elif t=='Binary': walk_expr(e.lhs); walk_expr(e.rhs)
        elif t in ('Unary','Postfix'): walk_expr(e.expr)
        elif t=='Member': walk_expr(e.expr); inc('Ident')
        elif t=='Index':
            walk_expr(e.expr)
            if e.index: walk_expr(e.index)
            if getattr(e,'slice_end',None): walk_expr(e.slice_end)
        elif t=='Call':
            if getattr(e,'options',None):
                walk_expr(e.func)
                for (n,v) in e.options.opts: inc('Ident'); walk_expr(v)
            else: walk_expr(e.func)
            inc('CallArgs'); incspan()
            if e.args:
                for a in e.args.args: walk_expr(a)
                if e.args.named:
                    for (n,v) in e.args.named.opts: walk_expr(v)
        elif t in ('Tuple','ArrayLit'):
            for x in e.elems:
                if x is not None: walk_expr(x)
        elif t=='Ternary': walk_expr(e.cond); walk_expr(e.true); walk_expr(e.false)
        elif t=='New': walk_type_expr(e.ty)
        elif t=='TypeExpr': walk_type_expr(e.ty)
        elif t=='TypeExpr2': walk_type_expr(e.ty)
        elif t=='PayableCall':
            inc('CallArgs'); incspan()
            if e.args:
                for a in e.args.args: walk_expr(a)
    def walk_type_expr(ty):
        if not ty: return
        cat={'elem':'Elementary','custom':'Custom','array':'Array','mapping':'Mapping','function':'Function'}.get(ty.kind[0],'Custom')
        inc('Type',cat); incspan()
        if ty.kind[0]=='custom':
            for tok in ty.kind[1]: inc('Ident')
        elif ty.kind[0]=='array':
            walk_type_expr(ty.kind[1])
            if ty.kind[2]: walk_expr(ty.kind[2])
        elif ty.kind[0]=='mapping':
            walk_type_expr(ty.kind[1]); walk_type_expr(ty.kind[3])
    def walk_block(block):
        if not block: return
        inc('Block'); incspan()
        for st in block.stmts: walk_stmt(st)
    def walk_stmt(st):
        if not st: return
        catmap={'ExprStmt':'Expr','VarDeclStmt':'DeclSingle','Block':'Block','If':'If','While':'While','DoWhile':'DoWhile','For':'For','Return':'Return','Break':'Break','Continue':'Continue','Emit':'Emit','Revert':'Revert','Try':'Try','Unchecked':'Unchecked','Assembly':'Assembly','Placeholder':'Placeholder','Throw':'Throw','TupleVarDecl':'DeclTuple'}
        inc('Stmt',catmap.get(st.typ,st.typ)); inc('DocComments'); incspan()
        t=st.typ
        if t=='Block': walk_block(st)
        elif t=='VarDeclStmt':
            inc('VariableDefinition')
            if st.var.initializer: walk_expr(st.var.initializer)
        elif t=='TupleVarDecl':
            for v in st.vars:
                if v: inc('VariableDefinition')
            if st.expr: walk_expr(st.expr)
        elif t=='ExprStmt': walk_expr(st.expr)
        elif t=='If':
            walk_expr(st.cond); walk_stmt(st.then)
            if st.else_: walk_stmt(st.else_)
        elif t=='While': walk_expr(st.cond); walk_stmt(st.body)
        elif t=='DoWhile': walk_stmt(st.body); walk_expr(st.cond)
        elif t=='For':
            if st.init: walk_stmt(st.init)
            if st.cond: walk_expr(st.cond)
            if st.post: walk_expr(st.post)
            walk_stmt(st.body)
        elif t=='Return':
            if st.expr: walk_expr(st.expr)
        elif t=='Revert':
            if st.expr: walk_expr(st.expr)
        elif t=='Emit': walk_expr(st.expr)
        elif t=='Try':
            walk_expr(st.expr)
            if st.returns:
                inc('ParameterList'); incspan()
                for v in st.returns.vars: inc('VariableDefinition')
            walk_block(st.body)
            for c in st.catches:
                if c.params:
                    inc('ParameterList'); incspan()
                    for v in c.params.vars: inc('VariableDefinition')
                walk_block(c.body)
        elif t=='Unchecked': walk_block(st.block)
        elif t=='Assembly': pass
    def walk_item(item):
        catmap={'ItemContract':'Contract','ItemFunction':'Function','VariableDefinition':'Variable','ItemStruct':'Struct','ItemEnum':'Enum','ItemEvent':'Event','ItemError':'Error','ItemUdvt':'Udvt','PragmaDirective':'Pragma','ImportDirective':'Import','UsingDirective':'Using'}
        inc('Item',catmap.get(item.kind_type,item.kind_type)); inc('DocComments'); incspan()
        kn=item.kind_node; kt=item.kind_type
        kindrow={'ItemContract':'ItemContract','ItemFunction':'ItemFunction','ItemStruct':'ItemStruct','ItemEnum':'ItemEnum','ItemEvent':'ItemEvent','ItemError':'ItemError','ItemUdvt':'ItemUdvt','PragmaDirective':'PragmaDirective','ImportDirective':'ImportDirective','UsingDirective':'UsingDirective'}.get(kt)
        if kindrow: inc(kindrow)
