        elif kt in ('ItemEvent','ItemError'):
            inc('ParameterList'); incspan()
            for v in kn.params.vars: inc('VariableDefinition')
        elif kt=='UsingDirective':
            for (path,alias) in kn.defs:
                if path: inc('PathSlice'); 
                for tok in (path or []): inc('Ident')
        # others no walk
    for info in infos:
        if not info.ast: continue
        inc('SourceUnit')
        for item in info.ast.items: walk_item(item)
    rows=[]
    total=0
    for name,cnt in counts.items():
        sz=sizes.get(name,16); acc=cnt*sz; rows.append((acc,name,cnt,sz)); total+=acc
    rows.sort(key=lambda x:(x[0],x[1]))
    def fmt_num(n):
