                lines.append(f"{('- '+cat):<24}{fmt_num(cacc):>4} ({cpct:4.1f}%){ccnt:>14}")
    lines.append("-"*64)
    lines.append(f"{'Total':<24}{fmt_num(total):>4}")
    lines.append("")
    return "".join(f"ast-stats {l}\n" if l else "ast-stats\n" for l in lines)

'''
